-- Rebuild Medina Book 3 lesson 10 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 41-43.
-- The Qur'anic string hidden by DOC control characters was transcribed literally from visible PDF page 42.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '10';
  if old_rule_count <> 3 then raise exception 'Expected 3 generated Book 3 lesson 10 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '10');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '10');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '10';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '10', 'الْجُمْلَةُ الِاسْمِيَّةُ (именное предложение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">الْجُمْلَةُ</span> نَوْعَانِ: <span class="ar-tone-subject">جُمْلَةٌ اسْمِيَّةٌ</span> وَ<span class="ar-tone-verb">جُمْلَةٌ فِعْلِيَّةٌ</span>.</span><p class="rule-study-text">Предложения делятся на именные и глагольные. Вид определяется тем, с какого элемента начинается предложение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">С чего начинается именное предложение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَدْرُ الْجُمْلَةِ</span><span class="rule-table-ru">начальный элемент</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْرِيفُ</span><span class="rule-table-ru">объяснение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمٌ صَرِيحٌ</span><span class="rule-table-ru">явно выраженное имя</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمٌ مَلْفُوظٌ بِهِ</span><span class="rule-table-ru">имя, выраженное непосредственно</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اللَّهُ غَفُورٌ. هَذِهِ مَدْرَسَةٌ. أَنَا مُجْتَهِدٌ. الطَّالِبُ غَائِبٌ. خَالِدٌ مَرِيضٌ.</span><span class="rule-table-ru">Аллах — Прощающий. Это школа. Я усердный. Студент отсутствует. Халид болен.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَصْدَرٌ مُؤَوَّلٌ</span><span class="rule-table-ru">истолковываемый масдар</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ الْمَصْدَرِيَّةُ مَعَ الْفِعْلِ تُؤَوَّلُ بِمَصْدَرٍ صَرِيحٍ</span><span class="rule-table-ru">частица «ан» с глаголом истолковывается как явный масдар</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْ تَبْقَى هُنَا أَحْسَنُ لَكَ.</span><span class="rule-table-ru">Тебе лучше остаться здесь.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفٌ مُشَبَّهٌ بِالْفِعْلِ</span><span class="rule-table-ru">частица, уподобленная глаголу</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنَّ وَأَخَوَاتُهَا</span><span class="rule-table-ru">«инна» и её сёстры</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنَّ اللَّهَ غَفُورٌ. لَيْتَنِي عَالِمٌ. كَأَنَّ الْكِتَابَ مُدَرِّسٌ.</span><span class="rule-table-ru">Поистине, Аллах — Прощающий. О если бы я был знающим. Как будто книга — преподаватель.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Истолковываемый масдар</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الْمُؤَوَّلُ</span><span class="rule-table-ru">конструкция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الصَّرِيحُ</span><span class="rule-table-ru">явный масдар</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">﴿ وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ ﴾</span><span class="rule-table-ru">«И поститься — лучше для вас»</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">صِيَامُكُمْ خَيْرٌ لَكُمْ.</span><span class="rule-table-ru">Ваш пост лучше для вас.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْ تَصُومُوا</span><span class="rule-table-ru">то, что вы поститесь; ваш пост</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْ تَبْقَى هُنَا أَحْسَنُ لَكَ.</span><span class="rule-table-ru">Тебе лучше остаться здесь.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">بَقَاؤُكَ أَحْسَنُ لَكَ.</span><span class="rule-table-ru">Твоё пребывание здесь лучше для тебя.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْ تَبْقَى</span><span class="rule-table-ru">то, что ты останешься; твоё пребывание</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Именное предложение начинается с явно выраженного имени, истолковываемого масдара либо одной из частиц, уподобленных глаголу.', 'الْجُمْلَةُ نَوْعَانِ: جُمْلَةٌ اسْمِيَّةٌ وَجُمْلَةٌ فِعْلِيَّةٌ. الْجُمْلَةُ الِاسْمِيَّةُ هِيَ الَّتِي يَكُونُ صَدْرُهَا اسْمًا صَرِيحًا، أَوْ مَصْدَرًا مُؤَوَّلًا، أَوْ حَرْفًا مُشَبَّهًا بِالْفِعْلِ.'),
    ('Мединский курс (Том 3)', '10', 'الْجُمْلَةُ الْفِعْلِيَّةُ وَالْفِعْلُ التَّامُّ وَالنَّاقِصُ (глагольное предложение, полный и неполный глагол)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">الْجُمْلَةُ الْفِعْلِيَّةُ</span> هِيَ الَّتِي يَكُونُ صَدْرُهَا فِعْلًا تَامًّا أَوْ فِعْلًا نَاقِصًا.</span><p class="rule-study-text">Глагольное предложение начинается с полного или неполного глагола.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный глагол</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْرِيفُ</span><span class="rule-table-ru">определение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَكْتَفِي بِفَاعِلِهِ وَيَتِمُّ بِهِ الْمَعْنَى</span><span class="rule-table-ru">довольствуется своим подлежащим, и смысл завершается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قَرَأَ عَلِيٌّ.</span><span class="rule-table-ru">Али прочитал.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فِعْلٌ وَفَاعِلٌ</span><span class="rule-table-ru">глагол и подлежащее</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ تَامٌّ</span><span class="rule-table-ru">полный глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">شَرِبَ مُحَمَّدٌ.</span><span class="rule-table-ru">Мухаммад выпил.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فِعْلٌ وَفَاعِلٌ</span><span class="rule-table-ru">глагол и подлежащее</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ تَامٌّ</span><span class="rule-table-ru">полный глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبَ سَعِيدٌ.</span><span class="rule-table-ru">Саид ушёл.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فِعْلٌ وَفَاعِلٌ</span><span class="rule-table-ru">глагол и подлежащее</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ تَامٌّ</span><span class="rule-table-ru">полный глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نَامَ الطِّفْلُ.</span><span class="rule-table-ru">Ребёнок уснул.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فِعْلٌ وَفَاعِلٌ</span><span class="rule-table-ru">глагол и подлежащее</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ تَامٌّ</span><span class="rule-table-ru">полный глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">طَلَعَتِ الشَّمْسُ.</span><span class="rule-table-ru">Солнце взошло.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فِعْلٌ وَفَاعِلٌ</span><span class="rule-table-ru">глагол и подлежащее</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ تَامٌّ</span><span class="rule-table-ru">полный глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خَرَجَتْ فَاطِمَةُ.</span><span class="rule-table-ru">Фатима вышла.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فِعْلٌ وَفَاعِلٌ</span><span class="rule-table-ru">глагол и подлежащее</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Неполный глагол</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْرِيفُ</span><span class="rule-table-ru">определение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَجْمُوعَةُ</span><span class="rule-table-ru">группа</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا يَكْتَفِي بِمَرْفُوعِهِ وَيَحْتَاجُ إِلَى مَنْصُوبٍ لِإِتْمَامِ الْمَعْنَى</span><span class="rule-table-ru">не довольствуется поднятым именем и нуждается в винительном компоненте</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَانَ وَأَخَوَاتُهَا</span><span class="rule-table-ru">«кана» и её сёстры</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَانَ الْجَوُّ بَارِدًا.</span><span class="rule-table-ru">Погода была холодной.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ نَاقِصٌ</span><span class="rule-table-ru">неполный глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَادَ وَأَخَوَاتُهَا</span><span class="rule-table-ru">«када» и её сёстры</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَادَ الطِّفْلُ يَسْقُطُ.</span><span class="rule-table-ru">Ребёнок едва не упал.</span></td></tr></tbody></table></div></div></div>', 2, 'rule', 'Глагольное предложение начинается с полного либо неполного глагола; полный довольствуется подлежащим, а неполному нужен ещё один компонент для завершения смысла.', 'الْجُمْلَةُ الْفِعْلِيَّةُ هِيَ الَّتِي يَكُونُ صَدْرُهَا فِعْلًا تَامًّا أَوْ فِعْلًا نَاقِصًا. الْفِعْلُ التَّامُّ يَكْتَفِي بِفَاعِلِهِ وَيَتِمُّ بِهِ الْمَعْنَى، وَالْفِعْلُ النَّاقِصُ لَا يَكْتَفِي بِمَرْفُوعِهِ وَيَحْتَاجُ إِلَى مَنْصُوبٍ لِإِتْمَامِ الْمَعْنَى.'),
    ('Мединский курс (Том 3)', '10', 'أَفْعَالُ الشُّرُوعِ (глаголы начала действия)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">أَفْعَالُ الشُّرُوعِ</span> أَفْعَالٌ نَاقِصَةٌ تَدُلُّ عَلَى الْبَدْءِ وَالشُّرُوعِ فِي الْفِعْلِ.</span><p class="rule-study-text">Эти неполные глаголы обозначают начало действия.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Перечень глаголов</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فِعْلُ الشُّرُوعِ</span><span class="rule-table-ru">глагол начала</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْشَأَ</span><span class="rule-table-ru">начал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَدَأَ</span><span class="rule-table-ru">начал</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَخَذَ</span><span class="rule-table-ru">принялся; начал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَدَأَ</span><span class="rule-table-ru">начал</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَعَلَ</span><span class="rule-table-ru">стал; начал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">شَرَعَ</span><span class="rule-table-ru">приступил</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">طَفِقَ</span><span class="rule-table-ru">принялся; начал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَدَأَ</span><span class="rule-table-ru">начал</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">شَرَعَ</span><span class="rule-table-ru">приступил; начал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَدَأَ</span><span class="rule-table-ru">начал</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Управление</span><span class="rule-main-ar" dir="rtl" lang="ar">تَعْمَلُ عَمَلَ <span class="ar-tone-verb">كَانَ</span>: تَرْفَعُ <span class="ar-tone-subject">الِاسْمَ</span>، وَتَنْصِبُ <span class="ar-tone-predicate">الْخَبَرَ</span>.</span><p class="rule-study-text">Имя глагола начала стоит в именительном падеже, а его сказуемое — в синтаксическом месте винительного падежа.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Обязательная форма сказуемого</span><span class="rule-main-ar ar-tone-predicate" dir="rtl" lang="ar">يَجِبُ أَنْ يَكُونَ خَبَرُهَا جُمْلَةً فِعْلِيَّةً فِعْلُهَا مُضَارِعٌ لَا يَقْتَرِنُ بِأَنْ الْمَصْدَرِيَّةِ مُطْلَقًا.</span><p class="rule-study-text">Сказуемое обязательно является глагольным предложением с глаголом настояще-будущего времени; частица «ан» к нему никогда не присоединяется.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры из шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَعَلَ الْمُدَرِّسُ يَشْرَحُ الدَّرْسَ.</span><span class="rule-table-ru">Преподаватель начал объяснять урок.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">شَرَعَ وَبَدَأَ بِالشَّرْحِ</span><span class="rule-table-ru">он приступил и начал объяснение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">طَفِقَ الطَّالِبُ يَكْتُبُ.</span><span class="rule-table-ru">Студент принялся писать.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَدَأَ بِالْكِتَابَةِ</span><span class="rule-table-ru">он начал писать</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">شَرَعَتِ الْأُمُّ تُعِدُّ الطَّعَامَ.</span><span class="rule-table-ru">Мать начала готовить еду.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَدَأَتْ بِإِعْدَادِ الطَّعَامِ</span><span class="rule-table-ru">она начала приготовление еды</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَنْشَأَ مُحَمَّدٌ يَقْرَأُ.</span><span class="rule-table-ru">Мухаммад начал читать.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَدَأَ بِالْقِرَاءَةِ</span><span class="rule-table-ru">он начал чтение</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный грамматический разбор</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَخَذَ</span><span class="rule-table-ru">принялся</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مَاضٍ نَاقِصٌ مَبْنِيٌّ عَلَى الْفَتْحِ</span><span class="rule-table-ru">неполный глагол прошедшего времени, построенный на фатхе</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَخَذَ الطَّالِبُ يَكْتُبُ.</span><span class="rule-table-ru">Студент принялся писать.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الطَّالِبُ</span><span class="rule-table-ru">студент</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ أَخَذَ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ</span><span class="rule-table-ru">имя глагола «ахаза», стоит в именительном падеже; признак — явно выраженная дамма</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ أَخَذَ</span><span class="rule-table-ru">имя глагола «ахаза»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَكْتُبُ</span><span class="rule-table-ru">пишет</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ</span><span class="rule-table-ru">глагол настояще-будущего времени в именительном состоянии; признак — явно выраженная дамма; подлежащее — скрытое местоимение «он»</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْفَاعِلُ: هُوَ</span><span class="rule-table-ru">подразумеваемое подлежащее: он</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَكْتُبُ</span><span class="rule-table-ru">глагольное предложение</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْجُمْلَةُ الْفِعْلِيَّةُ مِنَ الْفِعْلِ وَالْفَاعِلِ فِي مَحَلِّ نَصْبٍ خَبَرُ أَخَذَ</span><span class="rule-table-ru">глагольное предложение из глагола и подлежащего находится в синтаксическом месте винительного падежа как сказуемое глагола «ахаза»</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ أَخَذَ</span><span class="rule-table-ru">сказуемое глагола «ахаза»</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'Глаголы начала действия работают как «кана», но их сказуемым обязательно служит глагольное предложение с настояще-будущим глаголом без частицы «ан».', 'أَفْعَالُ الشُّرُوعِ أَفْعَالٌ نَاقِصَةٌ تَدُلُّ عَلَى الْبَدْءِ وَالشُّرُوعِ فِي الْفِعْلِ، وَهِيَ أَنْشَأَ وَأَخَذَ وَجَعَلَ وَطَفِقَ وَشَرَعَ. تَعْمَلُ عَمَلَ كَانَ فَتَرْفَعُ الِاسْمَ وَتَنْصِبُ الْخَبَرَ، وَيَجِبُ أَنْ يَكُونَ خَبَرُهَا جُمْلَةً فِعْلِيَّةً فِعْلُهَا مُضَارِعٌ لَا يَقْتَرِنُ بِأَنْ الْمَصْدَرِيَّةِ مُطْلَقًا.'),
    ('Мединский курс (Том 3)', '10', 'أَفْعَالُ الْمُقَارَبَةِ وَأَفْعَالُ الرَّجَاءِ (глаголы приближения и надежды)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">أَفْعَالُ الْمُقَارَبَةِ وَأَفْعَالُ الرَّجَاءِ</span> تَعْمَلُ عَمَلَ كَانَ.</span><p class="rule-study-text">Глаголы приближения действия и глаголы надежды управляют именем и сказуемым так же, как «кана».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Группы и примеры</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَجْمُوعَةُ</span><span class="rule-table-ru">группа</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَفْعَالُ</span><span class="rule-table-ru">глаголы и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَفْعَالُ الْمُقَارَبَةِ</span><span class="rule-table-ru">глаголы приближения</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَادَ، أَوْشَكَ</span><span class="rule-table-ru">едва не; почти; вот-вот</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَادَ الطِّفْلُ يَسْقُطُ.</span><span class="rule-table-ru">Ребёнок едва не упал.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَفْعَالُ الرَّجَاءِ</span><span class="rule-table-ru">глаголы надежды</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى، اِخْلَوْلَقَ</span><span class="rule-table-ru">возможно; есть надежда</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى الطَّالِبُ أَنْ يَنْجَحَ.</span><span class="rule-table-ru">Есть надежда, что студент преуспеет.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَفْعَالُ الرَّجَاءِ</span><span class="rule-table-ru">глаголы надежды</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِخْلَوْلَقَ</span><span class="rule-table-ru">есть надежда; вероятно</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِخْلَوْلَقَتِ السَّمَاءُ أَنْ تُمْطِرَ.</span><span class="rule-table-ru">Есть надежда, что небо прольётся дождём.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Частое присоединение частицы «ан»</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">يَكْثُرُ اقْتِرَانُ خَبَرِ أَوْشَكَ وَعَسَى وَاخْلَوْلَقَ بِأَنْ الْمَصْدَرِيَّةِ.</span><p class="rule-study-text">У глаголов «аушака», «аса» и «ихлауляка» сказуемое часто соединяется с масдарной частицей «ан».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Указание автора</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">سَنَدْرُسُ الْفِعْلَ أَوْشَكَ فِي الدَّرْسِ السَّابِعَ عَشَرَ إِنْ شَاءَ اللَّهُ.</span><p class="rule-study-text">Глагол «аушака» будет отдельно изучен в уроке 17, если пожелает Аллах.</p></div></div>', 4, 'rule', 'Глаголы приближения и надежды работают как «кана»; у трёх указанных в шархе глаголов сказуемое часто соединяется с частицей «ан».', 'أَفْعَالُ الْمُقَارَبَةِ وَأَفْعَالُ الرَّجَاءِ تَعْمَلُ عَمَلَ كَانَ. مِنْ أَفْعَالِ الْمُقَارَبَةِ كَادَ وَأَوْشَكَ، وَمِنْ أَفْعَالِ الرَّجَاءِ عَسَى وَاخْلَوْلَقَ. وَيَكْثُرُ اقْتِرَانُ خَبَرِ أَوْشَكَ وَعَسَى وَاخْلَوْلَقَ بِأَنْ الْمَصْدَرِيَّةِ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'الدَّرْسُ الْعَاشِرُ
الْجُمْلَةُ
الجملةُ ، نوعان : 1- جملةٌ اسْمِيَّةٌ                    2- جملةٌ فِعْلِيَّةٌ
( 1 ) الجملةُ الاسميةُ ، هي التي يكون صَدْرُها أَحَدَ الأشياء الآتية :
أ- اسمٌ صَرِيحٌ ، نحو : اللهُ غَفُورٌ. هذه مدرسةٌ. أَنَا مجتهدٌ. الطالبُ غائبٌ. خالدٌ مريضٌ .
ب- مَصْدَرٌ مُؤَوَّلٌ ، هو الذي يُؤَوَّل بَمَصْدَرٍ صريحٍ ، ويتكون مِنْ حرفِ الْمَصْدَرِ (أَنْ +
الِفعْل ) نحو قوله تعالى: ﴿ وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ ﴾ والتقدير : صيامكم خير لكم.
ونحو : أَنْ تَبْقَى هنا أحسنُ لك . والتقدير : بَقَاؤُك أحسنُ لك .
ج- حرْفٌ مُشَبَّهٌ بِالْفِعْلِ ، والأحرفُ الْمُشَبَّهَةُ بالفعلِ ، هي ( إِنَّ وأخواتها ) .
نحو : إِنَّ اللهَ غفورٌ ، لَيْتَنِي عَالِمٌ . كَأَنَّ الكتابَ مُدَرَّسٌ .', 41, 42, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '10' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', '( 2 ) الجملةُ الفعليَّةُ ، هي التي يكون صدرها أَحَدَ الأفعالِ الآتيةِ :
أ- فعلٌ تَامٌّ ، هو الذي يَكْتَفِي بِفَاعِلِهِ وَيَتِمُّ به المعنى ، نحو : قَرَأ عَلِيٌّ . شَرِبَ محمدٌ .
ذَهَبَ سعيدٌ . نَامَ الطّفلُ . طَلَعَتِ الشَّمْسُ . خَرَجَتْ فاطمةُ .
ب- فعلٌ نَاقِصٌ ، هو الذي لا يكتفِي بمرفوعِه ، ويحتاج إلى اسم منصوب لإِتْمَامِ المعنى .
الأفعالُ النَّاقصةُ ، هي : كان وأخواتها ، وكاد وأخواتها ، نحو : كانَ الجوُّ بارداً ،
كادَ الطفلُ يسقطُ .', 42, 42, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '10' and sort_order = 2;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'أَفْعَالُ الشُّرُوعِ
أفعالُ الشُّرُوعِ : أفعالٌ نَاقِصَةٌ تدلُّ على البَدْءِ والشُّرُوعِ بالِفعْل ، وهي : أَنْشَأَ ، وأَخَذَ ، وَجَعَلَ ، وطَفِقَ ، وشَرَعَ .
عَمَلُهَا : تعملُ عملَ كان ترفع الاسم ، وتنصب الخبر إِلاَّ أنَّ خبرها يجبُ أن يكون جملة فعليَّة فعلها مضارع لا يقترن بأَنْ المصدريَّة مُطْلقاً .
الأمثلة :
جَعَلَ المدرَّسُ يشرحُ الدرسَ ، أي : شَرَعَ وَبَدأَ بالشَّرْحِ .
طَفِقَ الطَّالبُ يكتبُ     .    شَرَعَتِ الأُمُّ تُعِدُّ الطَّعَامَ .
أَنْشَأَ محمدٌ يقرأُ   .
الإعراب : أَخَذَ الطالبُ يكتبُ .
أَخَذَ : فعل ماضٍ ناقص مبني على الفتح .
الطَّالبُ : اسم أخذ مرفوع وعلامته رفعه الضَّمَة الظَّاهرة .
